		'doroshopping_ui_legal_privacy_li1' => array( 'Identification and contact details: first name, surname, email, telephone number, shipping/billing address.', 'Identifikations- und Kontaktdaten: Vorname, Nachname, E-Mail, Telefonnummer, Liefer-/Rechnungsadresse.', 'Données d’identification et de contact : prénom, nom, e-mail, téléphone, adresse de livraison/facturation.', 'Dati identificativi e di contatto: nome, cognome, e-mail, telefono, indirizzo di spedizione/fatturazione.', 'Dados de identificação e contacto: nome, apelido, e-mail, telefone, morada de envio/faturação.' ),
		'doroshopping_ui_legal_privacy_li2' => array( 'Account and order data: purchase history, preferences and incidents.', 'Konto- und Bestelldaten: Kaufhistorie, Präferenzen und Vorfälle.', 'Données de compte et de commande : historique d’achat, préférences et incidents.', 'Dati dell’account e degli ordini: cronologia acquisti, preferenze e problemi.', 'Dados de conta e encomendas: histórico de compras, preferências e incidências.' ),
