		'doroshopping_ui_legal_privacy_li7' => array( 'Improve the website and security (legitimate interest).', 'Website und Sicherheit verbessern (berechtigtes Interesse).', 'Améliorer le site et la sécurité (intérêt légitime).', 'Migliorare il sito web e la sicurezza (interesse legittimo).', 'Melhorar o site e a segurança (interesse legítimo).' ),
		'doroshopping_ui_legal_privacy_li8' => array( 'Send commercial updates only with your consent, where applicable.', 'Werbliche Neuigkeiten nur mit Ihrer Einwilligung senden, sofern erforderlich.', 'Envoyer des communications commerciales uniquement avec votre consentement, le cas échéant.', 'Inviare comunicazioni commerciali solo con il tuo consenso, ove applicabile.', 'Enviar novidades comerciais apenas com o seu consentimento, quando aplicável.' ),
